 lessonContent.querySelectorAll('[data-act]').forEach(b=>{ b.onclick=()=>{ const en=decodeURIComponent(b.dataset.en||''), pt=decodeURIComponent(b.dataset.pt||''); const a=b.dataset.act; if(a==='en') speakEnglish(en); else if(a==='pt') speakPortuguese(pt); else if(a==='slow') speakSlow(en); else if(a==='bi') speakBilingual(en,pt); }; });
